/**
 * Þe Autumn Circus 0.0.0f (AutumnMood; Steamodded 1.0; needs AutumnMoodMechanics), rebuilt natively for Micatro.
 * Source: `Desktop/mods off/TheAutumnCircus-main` — modules/*.lua registered through data.lua's buffers,
 * overrides.lua, lovely.toml, localization/default.lua. Static fields come from data.js / loc.js (generated by
 * tools/micatro/extract_autumn.cjs, which runs the modules with config.lua's switches); behaviour is ported by hand:
 *   systems.js       10 Stamps, 12 Aspects, 4 enhancements, the Gilded edition, 2 tags, 2 blinds, 1 stake,
 *                    the Option Select pack, 12 vouchers, 9 decks, and overrides.lua / lovely.toml's rules
 *   jokers_a.js      LooksLikeTheJokers.lua, Standardized .. Gaudy Bracelet
 *   jokers_b.js      LooksLikeTheJokers.lua, Twisted Mind .. Amalgam Joker (+ the Homestuck jokers), Emojiokers.lua
 *   oddities.js      BasicOddities.lua (Oddities, AMM's type)
 *   consumables.js   MoreConsumables.lua: tarots, planets (incl. the suit planets: AMM suit levels), spectrals;
 *                    the MoreFluff cross-mod Rotarots / Colour (only while More Fluff is on too)
 * Cross-mod items carry `dependencies` (registry): they exist only while every partner mod is on.
 *
 * Owner decision (2026-10-16): the Homestuck content is in — the 12 Aspects and the Homelatro jokers (nekogloop,
 * autumnmood, the unnamed third player and the three God Tiers). Homelatro itself isn't in Micatro, so its two
 * rarities are defined here exactly as Homelatro's src/rarity.lua has them (github.com/factwixard/Homelatro,
 * 2025-08-27): Player (default_weight 0.35, #53A3FF) and God Tier (default_weight 0.25, #FF6000), with its
 * get_weight rules applied to the Players / God Tiers that exist here (see RARITIES below), and its
 * "Ascended!" / "Happen!" extinction strings.
 *
 * Skipped (they need mods Micatro doesn't ship): jokers Helpful / Dutiful Joker, Penumbra Phantasm, Onyx Moonmage,
 * Olivine (SixSuits), Amethyst Starmage, Meteorite (SixSuits + Ortalab), Paint Mixer, Celestial Awe
 * (SpectrumFramework), :currency_exchange: (pta_saka); the planets Shooting Star / Chill Moon and the Rotarot
 * flips (SixSuits); Journey, Experience Splitter (load_check); the Umbral / Bakery / Prestige / Star cards
 * (Aikoyori, SDM0's Stuff, 0 ERROR, Entropy); 25 cross-mod Oddities (Ortalab, Cryptid, Entropy, Revo's Vault,
 * GrabBag, Aikoyori, pta_saka, artbox); Overscaling / Hyperscaling (Stacked); the Lavender Deck (Aikoyori);
 * the GrabBag deck skins; the whole modules for JoyousSpring, GrabBag (BossMyJokers / ShatterMyJokers),
 * Entropy (selbamusnoCeroM), 0 ERROR (3ERROR) and Stacked (EffectsOnMyJokers); the Ortalab zodiac hooks.
 * Not ported (cosmetic): the title-screen card / logo / quips, card pronoun badges, art-credit tooltips.
 */
import { registerMod, isActive } from '../../js/mods/registry.js';
import { G, P_CENTER_POOLS, find_joker } from '../../js/engine/core.js';
import LOC from './loc.js';
import { MOD_ID, ART } from './util.js';
import * as SYS from './systems.js';
import * as JA from './jokers_a.js';
import * as JB from './jokers_b.js';
import * as ODD from './oddities.js';
import * as CON from './consumables.js';

const PARTS = [SYS, JA, JB, ODD, CON];

// Hooks: every module may define any hook; composed in PARTS order. Value-threading hooks pass each module's
// result on; list hooks concatenate; the rest call every module and keep the first answer.
const THREAD = new Set(['probability_vars', 'probability_pass', 'highlight_limit', 'selection_limit', 'consumable_highlight_count',
  'modify_scoring', 'joker_retriggers', 'chip_bonus', 'chip_mult', 'chip_x_mult', 'p_dollars', 'ease_dollars', 'draw_hand_space', 'booster_limit',
  'pack_choices', 'pack_size', 'cash_out', 'reroll_cost', 'edition_weight']);
const LISTS = new Set(['evaluate_round', 'seal_retriggers', 'scoring_areas', 'card_repetitions', 'unscored_card']);
const hooks = {};
for (const name of new Set(PARTS.flatMap((p) => Object.keys(p.hooks || {})))) {
  const fns = PARTS.map((p) => p.hooks && p.hooks[name]).filter(Boolean);
  if (fns.length === 1) { hooks[name] = fns[0]; continue; }
  if (THREAD.has(name)) hooks[name] = (v, ...a) => { for (const f of fns) { const r = f(v, ...a); if (r !== undefined) v = r; } return v; };
  else if (LISTS.has(name)) hooks[name] = (...a) => { let out; for (const f of fns) { const r = f(...a); if (r !== undefined) out = (out || []).concat(r); } return out; };
  else hooks[name] = (...a) => { let out; for (const f of fns) { const r = f(...a); if (out === undefined && r !== undefined) out = r; } return out; };
}

const at = (file, px = 71, py = 95, extra = {}) => ({ src: ART + file + '.png', px, py, ...extra });
const atlases = {
  thac_LooksLikeTheJokers: at('LooksLikeTheJokers'),
  thac_specialjoker: at('specialjoker', 113, 113),
  thac_Emojiokers: at('Emojiokers', 84, 112),
  thac_MoreConsumables: at('MoreConsumables'),
  thac_Rotatema: at('Rotatema', 107, 107),
  thac_BasicOddities: at('BasicOddities'),
  thac_JokerStamps: at('JokerStamps'),
  thac_HamSpect: at('HamSpect'),
  thac_Enhancable: at('Enhancable'),
  thac_VouchMe: at('VouchMe'),
  thac_DeckTheBalatro: at('DeckTheBalatro'),
  thac_BlindToAllButTheVideo: at('BlindToAllButTheVideo', 34, 34, { frames: 21 }),
  thac_ShowdownThrowdown: at('ShowdownThrowdown', 34, 34, { frames: 21 }),
  thac_TagImIt: at('TagImIt', 34, 34),
  thac_TransGirlsWhoBooster: at('TransGirlsWhoBooster'),
  thac_StakeMePls: at('StakeMePls', 29, 29),
  thac_StakeMyCardsPls: at('StakeMyCardsPls'),
};

/**
 * The Homelatro rarities (Homelatro src/rarity.lua; see the header). get_weight, over the Homestuck jokers that exist
 * here: a Player rolls until every Player has gone extinct (Homelatro: "not (every *_extinct flag)"); a God Tier rolls
 * while some God Tier's Player is extinct and that God Tier isn't held (Showman excepted: Homelatro's
 * "flag and (SMODS.showman() or not next(SMODS.find_card(god tier)))").
 */
const hmlt = (rarity) => (P_CENTER_POOLS.Joker || []).filter((c) => c.rarity === rarity);
const flag = (f) => !!(G.GAME && G.GAME.pool_flags && G.GAME.pool_flags[f]);
const players_left = () => hmlt('hmlt_player').some((c) => !(c.no_pool_flag && flag(c.no_pool_flag)));
const godtier_available = () => {
  const showman = !!(G.jokers && find_joker('Showman').length);
  return hmlt('hmlt_godtier').some((c) => c.yes_pool_flag && flag(c.yes_pool_flag) &&
    (showman || !(G.jokers && G.jokers.cards.some((j) => j.config.center.key === c.key))));
};
export const RARITIES = [
  { key: 'hmlt_player', name: 'Player', weight: 0.35, badge_colour: '#53A3FF', get_weight: (r) => (players_left() ? r.weight : 0) },
  { key: 'hmlt_godtier', name: 'God Tier', weight: 0.25, badge_colour: '#FF6000', get_weight: (r) => (godtier_available() ? r.weight : 0) },
];
// Homelatro's localization (en-us.lua misc.dictionary): the Players' end-of-round extinction popups.
Object.assign(LOC.misc.dictionary, { hmlt_extinct: 'Ascended!', hmlt_safe: 'Happen!', k_hmlt_player: 'Player', k_hmlt_godtier: 'God Tier' });

// SMODS multi-line names ({name = {'Cultist Potion', '{C:autumn,s:0.5}CAW CAW!!!!'}}): the first line is the name,
// the rest a small subtitle (kept as `name_sub`).
for (const set of Object.values(LOC.descriptions || {})) {
  for (const d of Object.values(set || {})) if (d && Array.isArray(d.name)) { d.name_sub = d.name.slice(1); d.name = d.name[0]; }
}

const centers = PARTS.flatMap((p) => p.centers || []).filter(Boolean);
export const CIRCUS = registerMod({
  id: MOD_ID,
  name: 'Þe Autumn Circus',
  prefix: 'thac',
  version: '0.0.0f',
  by: 'AutumnMood (rebuilt for Micatro)',
  requires: ['autumnmood'],
  badge_colour: '#00164F',
  description: 'Welcome to Þe Autumn Circus! Jokers, Oddities, new tarots/planets/spectrals, decks, stamps, aspects and more.',
  // SMODS optional features (TheAutumnCircus.lua): the 'unscored' card area, AMM's Suits tab and graveyard tab
  optional_features: { retrigger_joker: true, post_trigger: true, unscored: true, amm_suit_levels: true, amm_graveyard: true },
  content: {
    centers,
    seals: SYS.seals,
    tags: PARTS.flatMap((p) => p.tags || []),
    blinds: PARTS.flatMap((p) => p.blinds || []),
    stakes: SYS.stakes,
    rarities: RARITIES,
    atlases,
    fonts: { thac_emoji: { src: '/micatro/mods/autumncircus/assets/fonts/NotoEmoji-Bold.ttf', family: 'thac_emoji' } },
    loc: LOC,
  },
  hooks,
});

const keys = (set) => centers.filter((c) => c.set === set).map((c) => c.key);
export const STATUS = {
  jokers: keys('Joker'),
  oddities: keys('Oddity'),
  tarots: keys('Tarot'),
  planets: keys('Planet'),
  spectrals: keys('Spectral'),
  rotarots: keys('Rotarot'),
  colours: keys('Colour'),
  vouchers: keys('Voucher'),
  decks: keys('Back'),
  enhancements: keys('Enhanced'),
  editions: keys('Edition'),
  boosters: keys('Booster'),
  stamps: SYS.stamps.map((s) => s.key),
  aspects: SYS.aspects.map((a) => a.key),
  tags: PARTS.flatMap((p) => p.tags || []).map((t) => t.key),
  blinds: PARTS.flatMap((p) => p.blinds || []).map((b) => b.key),
  stakes: SYS.stakes.map((s) => s.key),
};
export { isActive };
